#!/bin/zsh
# Refreshes the GitHub release "records" from a copy of the site's database, such as the one
# backup-to-mac.sh has just rebuilt, so that the mirror costs the site no outbound data: the copy
# reached this Mac over Fly's private network, and the files go from here to GitHub.
#
# It runs the site's own server (polypack-server, the Rust build) on the copy, reachable from this
# Mac only, lets it build the snapshot's manifest as the site does every night, and runs
# mirror-snapshot.ts against it. So the files are generated by the code that generates the site's,
# and only the piece shapes whose records changed since the release's last copy are uploaded.
#   mirror-from-backup.sh database.sqlite [as_of]
# `as_of` is when the copy's records were the site's (backup-rebuild.mjs reports it); the release
# notes give it. The server writes to the copy it is given (its start-up steps, a write-ahead log),
# so give it one that is not kept.
#
# Installed by `backup-to-mac.sh install`, which puts the server, the data/ files it reads and
# mirror-snapshot.ts in mirror/ beside this script. Run from a checkout, it takes them from the
# checkout (build the server first: cargo build --release -p polypack-server in native/). Needs
# node 24 or newer and gh signed in with write access to the repository.
# Settings, all optional: POLYPACK_MIRROR_PORT (18788), POLYPACK_MIRROR_WAIT (seconds to wait for
# the manifest, 1800; the server begins it 5 minutes after it starts).
set -euo pipefail
export PATH="/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin"

HERE="${0:A:h}"
DB="${1:?usage: mirror-from-backup.sh database.sqlite [as_of]}"
DB="${DB:A}"
AS_OF="${2:-}"
PORT="${POLYPACK_MIRROR_PORT:-18788}"
WAIT="${POLYPACK_MIRROR_WAIT:-1800}"
if [[ -x "$HERE/mirror/polypack-server" ]]; then
  ROOT="$HERE/mirror"
  SERVER="$ROOT/polypack-server"
  MIRROR="$ROOT/mirror-snapshot.ts"
else
  ROOT="${HERE:h:h}"
  SERVER="$ROOT/native/target/release/polypack-server"
  MIRROR="$ROOT/scripts/mirror-snapshot.ts"
fi
[[ -f "$DB" ]] || { print -u2 "no database at $DB"; exit 1; }
[[ -x "$SERVER" && -f "$MIRROR" && -f "$ROOT/data/records.json" ]] ||
  { print -u2 "the server, mirror-snapshot.ts or data/ is missing under $ROOT"; exit 1; }
LOCAL="http://127.0.0.1:$PORT"
if curl -s -o /dev/null --max-time 2 "$LOCAL/api/health"; then
  print -u2 "something already answers on port $PORT; set POLYPACK_MIRROR_PORT"
  exit 1
fi

snap=$(mktemp -d "${TMPDIR:-/tmp}/polypack-mirror.XXXXXX")
pid=""
stop() {
  [[ -n "$pid" ]] && kill "$pid" 2> /dev/null && wait "$pid" 2> /dev/null
  rm -rf "$snap"
}
trap stop EXIT

# The server reads data/ below its working directory. None of the site's secrets reach it, so
# nothing can be submitted or moderated through it; its snapshot is built in $snap.
(
  cd "$ROOT"
  exec env -u ADMIN_TOKEN -u SUBMIT_KEY -u TRUST_PROXY -u CLIENT_IP_HEADER -u POLYPACK_TEST_OPTIONS \
    DATABASE_PATH="$DB" SNAPSHOT_DIR="$snap/snapshot" HOST=127.0.0.1 PORT="$PORT" \
    PIECES_MIGRATION_BATCH=0 "$SERVER"
) > "$snap/server.log" 2>&1 &
pid=$!

# The manifest is finished when its completed_at is its generated_at.
finished() {
  curl -sf --max-time 30 "$LOCAL/api/snapshot" 2> /dev/null |
    node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const m=JSON.parse(s);process.exit(m.completed_at&&m.completed_at===m.generated_at?0:1)}catch{process.exit(1)}})'
}
started=$SECONDS
until finished; do
  if ! kill -0 "$pid" 2> /dev/null; then
    pid=""
    print -u2 "the server stopped: $(tail -5 "$snap/server.log")"
    exit 1
  fi
  if ((SECONDS - started > WAIT)); then
    print -u2 "no finished manifest after $WAIT s: $(tail -5 "$snap/server.log")"
    exit 1
  fi
  sleep 15
done
print "the copy's snapshot manifest was built in $((SECONDS - started)) s"

POLYPACK_SOURCE="$LOCAL" POLYPACK_AS_OF="$AS_OF" node "$MIRROR"
